CREATE TRIGGER trigger_partogram_grade_rule_updated_at
    BEFORE UPDATE ON partogram_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE partogram_grade_rule IS
